package com.zoutiw.bibla.data

object JoelData {
    val verses: List<Verse> = listOf(
        Verse(book = "Jowèl", chapter = 1, verseNumber = 1, text = "Men mesaj Seyè a te bay Joèl, pitit gason Petwèl la.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 2, text = "Nou menm vye granmoun yo, koute byen! Nou menm ki rete nan peyi Jida a, louvri zòrèy nou! Eske nan tan pa nou, osinon nan tan zansèt nou yo bagay konsa te janm rive?", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 3, text = "N'a rakonte pitit nou yo sa. Yo menm, y'a rakonte pitit pa yo sa. Lèfini, pitit yo menm va rakonte l' bay moun k'ap vin apre yo.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 4, text = "Sa jenn ti krikèt yo kite, gwo krikèt devore sa. Sa gwo krikèt yo kite, ti chini devore sa. Sa ti chini yo kite, gwo chini devore sa.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 5, text = "Leve non, bann gwògè! Kriye non! Nou menm ki renmen bweson, pete rele! Paske pa gen rezen pou fè diven nivo pou nou ankò.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 6, text = "Yon lame krikèt atake peyi nou an. Yo gwonèg, moun pa ka konte yo. Dan yo tankou dan lyon, kwòk dan yo tankou dan femèl lyon.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 7, text = "Yo fini ak jaden rezen nou yo. Yo manje tout pye fig frans nou yo. Yo wete tout kòs pye fig frans yo voye jete atè. Branch pye rezen yo rete kanpe tou blan.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 8, text = "Nou menm pèp la, nou mèt plenn, tankou yon jenn fi, rad sak li sou li, k'ap plenn lanmò fiyanse l'.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 9, text = "Pa gen grenn jaden, ni diven pou fè ofrann nan tanp Seyè a. Prèt yo, sèvitè Seyè a, nan lapenn.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 10, text = "Tout jaden yo blanch. Tè a nan lapenn. Tout pye ble yo fin mouri. Pye rezen yo cheche. Pye oliv yo rabougri.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 11, text = "Kiltivatè yo pa konn sa pou yo fè. Moun k'ap okipe jaden rezen yo ap plenn paske pa gen ble, pa gen lòj. Tout rekòt yo pèdi nèt.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 12, text = "Pye rezen yo ap cheche, pye fig frans yo ap mouri. Pye grenad, pye palmis, pye ponm, tout pye fwi nan jaden fin fennen. Pa gen moun ki gen kè kontan ankò.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 13, text = "Nou menm prèt yo, mete rad sak sou nou! Pete rele! Nou menm k'ap sèvi devan lotèl la, mare ren nou. Ale nan tanp lan, pase nwit lan ak rad sak sou nou. Nou menm k'ap fè sèvis pou Bondye m' lan, nou nan lapenn. Pa gen grenn jaden, pa gen diven pou fè ofrann nan kay Bondye nou an.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 14, text = "Bay lòd pou yo fè jèn! Rele tout moun vini! Sanble tout chèf yo ansanm ak tout moun ki rete nan peyi a, nan kay Seyè a, Bondye nou an. Rele nan pye Seyè a.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 15, text = "Ala yon gwo jou papa! Jou Seyè a pa lwen rive. Se jou Bondye ki gen tout pouvwa a ap vini kraze brize. Jou sa a ap bay gwo lapenn.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 16, text = "N'ap gade konsa, rekòt nou yo ap disparèt devan je nou san nou pa ka fè anyen! Pa gen kè kontan, pa gen fèt nan kay Bondye nou an!", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 17, text = "Grenn yo plante yo rete anba tè. Kay depo yo fin kraze. Galata yo vid. Pa gen rekòt pou mete ladan yo.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 18, text = "Zannimo yo ap plenn, bann bèf yo pa konn kote pou yo ale. Yo pa jwenn anyen pou yo manje nan savann. Ata mouton yo ap soufri grangou.", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 19, text = "Seyè, m'ap rele nan pye ou! paske chechrès la fini ak jaden zèb yo. Ou ta di se dife ki boule tout pyebwa yo!", bookId = 29),
        Verse(book = "Jowèl", chapter = 1, verseNumber = 20, text = "Ata zannimo nan savann yo ap rele nan pye ou, paske tout larivyè yo chèch nèt. Dife boule tout zèb nan savann yo.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 1, text = "Kònen twonpèt sou mòn Siyon an! Bay siyal la sou mòn ki apa pou Bondye a! Se pou tout moun nan peyi Jida a tranble, paske jou Seyè a pa lwen rive. L'ap pwoche.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 2, text = "Se va yon jou ki pral fè nwa kou lank, ak syèl la plen nwaj nwa, yon jou kote nwaj nwa ak pousyè pral kouvri latè. Yon lame krikèt ap vanse. Yo gwonèg anpil! Tankou solèy la lè l'ap leve, y'ap kouvri mòn yo. Se bagay nou poko janm wè, bagay nou p'ap janm wè ankò, jouk sa kaba.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 3, text = "Tankou dife, yo devore tou sa ki devan yo. Yo pa kite anyen kote yo pase. Anvan yo te vini, peyi a te tankou yon ti paradi. Lè yo fin pase, li tounen yon dezè san anyen ladan l'. Anyen pa chape anba dan yo.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 4, text = "Yo tankou chwal, yo kouri tankou chwal sèl.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 5, text = "Lè y'ap soti sou tèt mòn yo, yo fè yon bri tankou cha lagè k'ap pase, tankou dife nan pay chèch. Yo mache an ran tankou yon gwo lame tou pare pou goumen.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 6, text = "Lè y'ap pwoche, tout moun pran tranble. Figi tout moun dekonpoze.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 7, text = "Yo atake tankou vanyan sòlda. Yo moute sou miray yo tankou sòlda k'ap fè lagè. Yo mache dwat devan yo, yo pa vire ni adwat ni agoch.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 8, text = "Yonn pa antrave lòt nan mach yo. Yo chak ap swiv chemen pa yo. Yo janbe tou sa yo mete pou bare yo. Anyen pa rete yo.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 9, text = "Yo pran lavil la pou yo. Yo kouri moute sou miray yo. Yo moute anwo kay yo, yo pase antre nan fennèt yo tankou vòlò.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 10, text = "Tè a souke lè y'ap mache vini. Syèl la tranble. Solèy la ak lalin lan vin tou nwa, zetwal yo pa klere nan syèl la ankò.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 11, text = "Seyè a ap mache alatèt lame li a: l'ap pase yo lòd. Lame a anpil. Yo gwonèg: Y'ap fè sa li ba yo lòd fè a. Ala yon gwo jou se jou Seyè a! Se yon jou pou moun pè tout bon vre. Ki moun ki va rete kanpe apre jou sa a?", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 12, text = "Seyè a pale, li di: -Menm koulye a, tounen vin jwenn mwen ak tout kè nou! Fè jèn, kriye kont kò nou, plenn sò nou!", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 13, text = "Se pa rad sou nou pou nou chire, se kè nou menm pou nou chire pou fè wè jan nou nan lapenn. Tounen vin jwenn Seyè a, Bondye nou an. Li gen bon kè anpil, li gen pitye pou moun. Li pa fache fasil, li p'ap janm sispann renmen nou. Li toujou pare pou padonnen nou.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 14, text = "Sa ki konnen? Li ka chanje lide, li ka padonnen nou. Li ka ban nou benediksyon. N'a gen grenn jaden ak diven ankò pou nou fè ofrann bay Seyè a, Bondye nou an!", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 15, text = "Kònen twonpèt sou mòn Siyon an! Bay lòd pou tout moun fè jèn! Mande pou tout moun reyini!", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 16, text = "Sanble pèp la. Pare tout moun pou fè sèvis. Sanble vye granmoun yo! Reyini tout timoun yo, menm timoun ki nan tete. Ata moun ki fenk marye yo, se pou yo kite kay yo vini tou.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 17, text = "Nan lakou ki separe gwo pòtay tanp lan ak lotèl la, se pou prèt yo, sèvitè Seyè a, pran kriye. Se pou yo di: Pitye, Seyè, pitye pou pèp ou a. Pa kite moun lòt nasyon yo pase moun pa ou yo nan betiz pou fè yo wont, pou yo ta di: Kote Bondye yo a?", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 18, text = "Lè sa a, Seyè a fè wè jan li renmen peyi li a. Li fè pèp li a gras.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 19, text = "Li reponn, li di pèp la konsa: -Bon! Mwen pral ban nou ble, diven ak lwil fre. N'ap gen tou sa n'a bezwen. Mwen p'ap janm kite moun lòt nasyon yo pase nou nan betiz ankò.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 20, text = "Mwen pral chase lame krikèt la byen lwen nou. Wi, lame krikèt ki te soti nan nò a. M'ap voye yo ale nan dezè a, kote ki pa gen dlo, kote ki pa gen pyebwa. Tèt lame krikèt yo va pran direksyon lanmè ki sou bò solèy leve a, lanmè Mouri a. Ke lame krikèt yo va pran direksyon lanmè ki sou bò solèy kouche a, lanmè Mediterane a. Kadav yo pral pouri, y'ap bay move sant. Seyè a fè anpil bagay pou nou.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 21, text = "Nou menm jaden yo, nou pa bezwen pè ankò. Fè fèt, fè kè nou kontan, paske Seyè a fè anpil pou nou!", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 22, text = "Nou menm zannimo nan savann yo, nou pa bezwen pè ankò: jaden zèb yo pral pouse byen bèl, pyebwa yo pral donnen, pye fig frans yo ak pye rezen yo pral bay bèl rekòt.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 23, text = "Nou menm, moun Siyon yo, fè fèt! Fè kè nou kontan poutèt sa Seyè a, Bondye nou an, fè pou nou. Li ban nou kantite lapli nou te bezwen nan sezon lotòn. Li ban nou gwo lapli loraj ak lapli nan sezon prentan, jan l' te konn fè l' anvan an.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 24, text = "Glasi yo pral plen grenn. Barik yo pral plen diven ak lwil fre.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 25, text = "M'a ban nou ankò tou sa nou te pèdi pandan tout tan bann gwo krikèt yo, ti krikèt yo, ti chini yo ak gwo chini yo te devore rekòt nou yo. Se mwen menm ki te voye lame sa a sou nou.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 26, text = "Nou pral manje plen vant nou. N'a fè lwanj Seyè a, Bondye nou an, ki te fè tout bèl bagay sa yo pou nou. Yo p'ap janm pase pèp mwen an nan betiz ankò.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 27, text = "Lè sa a, n'a konnen mwen kanpe la nan mitan pèp Izrayèl la. Se mwen menm Seyè a ki Bondye nou. Pa gen tankou m'. Yo p'ap janm pase pèp mwen an nan betiz ankò.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 28, text = "Apre sa, m'a vide lespri mwen sou tout moun. Pitit gason ak pitit fi nou yo va bay mesaj m'a ba yo. Granmoun nou yo va fè rèv. Jennmoun nou yo va gen vizyon.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 29, text = "Wi, lè sa a, m'a vide lespri m' sou tout moun, ata sou moun k'ap travay lakay nou, fi kou gason.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 30, text = "M'apral fè mèvèy parèt nan syèl la ak sou latè a. Va gen san, dife ak gwo nwaj lafimen.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 31, text = "Solèy la pral vin tou nwa, lalin lan pral vin wouj kou san anvan jou Seyè a va rive. Aa! Se va yon gwo jou, yon jou k'ap fè moun tranble.", bookId = 29),
        Verse(book = "Jowèl", chapter = 2, verseNumber = 32, text = "Lè sa a, tout moun ki va rele nan pye Seyè a va sove. Paske sou mòn Siyon ak nan lavil Jerizalèm va gen moun ki va chape, jan Seyè a te di l' la. Wi, tout moun Seyè a va chwazi, se yo ki va chape.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 1, text = "Seyè a di ankò: -Lè sa a, jou sa yo, m'a fè peyi Jida a ak lavil Jerizalèm kanpe ankò.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 2, text = "Apre sa, m'a sanble tout nasyon yo. M'a fè yo desann nan Fon Jijman Bondye a. Se la mwen pral jije yo pou tou sa yo fè Izrayèl, pèp mwen an, moun pa m' yo. Paske, se yo ki te gaye moun pèp Izrayèl yo nan mitan lòt nasyon yo. Lèfini, yo te separe peyi mwen an.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 3, text = "Yo te tire osò pou konnen pou ki moun prizonye yo ap ye. Yo te vann ti gason yo pou yo te ka gen lajan pou al nan jennès. Yo te vann tifi yo pou yo te ka gen lajan pou achte bweson, Lèfini, yo bwè jouk yo sou.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 4, text = "Nou menm moun lavil Tir ak moun lavil Sidon, sa n'ap chache fè m' konsa? Nou menm tou ki rete nan tout zòn peyi Filisti a, se chache n'ap chache fè m' peye pou sa m' te fè nou? Si nou vle tire revanj nou sou mwen, enben, anvan nou bat je nou, m'ap fè nou peye sa.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 5, text = "Nou te pran tout ajan ak tout lò mwen yo, nou pote tout bèl gwo richès mwen yo ale nan tanp nou yo.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 6, text = "Nou pran moun peyi Jida yo ak moun lavil Jerizalèm yo, nou mennen yo byen lwen peyi yo: n' al vann yo bay moun peyi Lagrès.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 7, text = "Koulye a, mwen pral fè yo soti kote nou te vann yo a. Mwen pral fè nou sa nou te fè yo a.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 8, text = "Mwen pral vann pitit gason ak pitit fi nou yo. Mwen pral lage yo nan men moun Jida yo. Yo menm, yo pral vann yo bay sabeyen yo ki rete nan yon peyi byen lwen. Se mwen menm, Seyè a, ki di sa.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 9, text = "Mache fè piblikasyon sa a nan mitan tout nasyon yo! Pare nou pou n' al fè lagè pou Bondye! Rele tout vanyan gason yo! Sanble tout sòlda yo! Fè yo mache pran yo!", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 10, text = "Pran lam fè ki nan chari nou yo fè nepe. Pran kouto digo nou yo, fè fwenn ak yo. Menm moun ki pi fèb yo pral di yo vanyan gason.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 11, text = "Nou menm, tout nasyon ki sou lizyè fwontyè peyi a, prese non! Kouri vini! Sanble nan fon an! Seyè, voye vanyan sòlda ou yo al atake yo!", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 12, text = "Se pou tout nasyon ki sou lizyè fwontyè peyi a sanble tout lame yo pou yo vini nan Fon Jijman an, paske se la mwen pral chita pou m' jije tout nasyon ki sou lizyè fwontyè peyi a.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 13, text = "Moun sa yo twò mechan. Koupe tèt yo tankou lè n'ap ranmase rekòt ki mi. Kraze yo anba pye nou tankou lè n'ap kraze rezen nan basen pou fè diven. Barik ji rezen yo plen ap debòde.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 14, text = "Foul moun sou foul moun nan Fon Jijman an! Paske jou Seyè a pa lwen rive nan Fon Jijman an.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 15, text = "Solèy la ak lalin lan vin tou nwa. Zetwal yo pa klere nan syèl la.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 16, text = "Seyè a rete sou mòn Siyon, l'ap gwonde. Li rete lavil Jerizalèm, l'ap pale byen fò. Syèl la ak latè a ap tranble. Men, se Seyè a k'ap pwoteje pèp li a. Se li k'ap pran defans moun Izrayèl yo.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 17, text = "Lè sa a, n'a konnen se mwen menm ki Seyè a, Bondye nou an. Mwen rete sou mòn Siyon, mòn yo mete apa pou mwen an. Jerizalèm va yon lavil apa pou Bondye. Moun lòt nasyon yo p'ap ka pran l' pou yo ankò.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 18, text = "Jou sa a, mòn yo pral kouvri ak jaden rezen. Bèf pral sou tout ti mòn yo. Va gen kont dlo nan larivyè peyi Jida yo. Yon sous dlo pral koule soti nan kay Seyè a. Li pral wouze bafon zakasya yo.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 19, text = "Peyi Lejip pral tounen yon savann dezole. Peyi Edon pral tounen yon dezè. Paske, yo te fè moun peyi Jida yo mechanste, yo te touye yon bann inonsan nan peyi yo.", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 20, text = "-(we vèsè pwochen)", bookId = 29),
        Verse(book = "Jowèl", chapter = 3, verseNumber = 21, text = "Men, m'a pran revanj moun yo te touye yo. Mwen p'ap fè pa moun ki koupab yo. Men, va gen moun rete nan peyi Jida a ak nan lavil Jerizalèm pou tout tan. Epitou, mwen menm, Seyè a, m'a fè mòn Siyon an tounen kay mwen ankò.", bookId = 29)
    )
}

